const fs=require('node:fs'),assert=require('node:assert/strict');const {H,OUT}=require('./simulate-walkthrough-p2-20261101.cjs');
const native=H.importStr(fs.readFileSync(OUT+'/checkpoint-1day-native.ht5','utf8')),batched=H.importStr(fs.readFileSync(OUT+'/checkpoint-1day.ht5','utf8'));
const hard=[],floats=[];function diff(a,b,p='state'){if(p==='state.last')return;if(typeof a!==typeof b){hard.push({path:p,type:'type'});return;}if(a===null||b===null){if(a!==b)hard.push({path:p,type:'null'});return;}if(typeof a==='number'){if(a===b)return;const error=Math.abs(a-b),limit=1e-5+Math.max(Math.abs(a),Math.abs(b))*2e-9;if(error>limit)hard.push({path:p,type:'numeric',error,limit});else floats.push({path:p,error,limit});return;}if(typeof a!=='object'){if(a!==b)hard.push({path:p,type:'value'});return;}const ak=Object.keys(a).sort(),bk=Object.keys(b).sort();if(JSON.stringify(ak)!==JSON.stringify(bk)){hard.push({path:p,type:'keys'});return;}for(const k of ak)diff(a[k],b[k],p+'.'+k);}
diff(JSON.parse(H.save(native)),JSON.parse(H.save(batched)));const result={nativeWholeDaySteps:JSON.parse(fs.readFileSync(OUT+'/native-1day.json','utf8')).steps,discreteAndStringMismatchCount:hard.filter(x=>x.type!=='numeric').length,hardMismatchCount:hard.length,hardMismatches:hard,floatingValuesWithinTolerance:floats.length,maxAbsoluteFloatingDifference:Math.max(0,...floats.map(x=>x.error)),numericTolerance:'1e-5 absolute + 2e-9 relative; wall-clock last excluded; all structure/string/discrete counters must match',roundsExactlyEqual:native.legacy.round===batched.legacy.round,pointsExactlyEqual:native.legacy.points===batched.legacy.points,eraExactlyEqual:native.era===batched.era,archiveExactlyEqual:JSON.stringify(native.archive)===JSON.stringify(batched.archive),blueprintIDsExactlyEqual:JSON.stringify(native.blueprints.map(x=>x.id))===JSON.stringify(batched.blueprints.map(x=>x.id)),workshopExactlyEqual:JSON.stringify(native.workshop)===JSON.stringify(batched.workshop)};fs.writeFileSync(OUT+'/native-versus-cycle-day.json',JSON.stringify(result,null,2));console.log(JSON.stringify(result,null,2));assert(!hard.length);
